describe('Image Alt Text Accessibility', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should have descriptive alt text for all images on the page', () => {
    cy.get('img').each(($img) => {
      cy.wrap($img)
        .should('have.attr', 'alt')
        .and('not.be.empty');

      const altText = $img.attr('alt');
      expect(altText.length).to.be.greaterThan(3);
      expect(altText).to.not.match(/^image|^photo|^pic$/i);
    });
  });

  it('should have alt text for decorative images marked appropriately', () => {
    cy.get('img[role="presentation"]').each(($img) => {
      cy.wrap($img)
        .should('have.attr', 'alt')
        .and('equal', '');
    });

    cy.get('img[aria-hidden="true"]').each(($img) => {
      cy.wrap($img)
        .should('have.attr', 'alt')
        .and('equal', '');
    });
  });

  it('should have meaningful alt text for content images', () => {
    cy.get('img:not([role="presentation"]):not([aria-hidden="true"])').each(($img) => {
      const altText = $img.attr('alt');

      expect(altText).to.exist;
      expect(altText).to.not.be.empty;
      expect(altText.length).to.be.greaterThan(5);
      expect(altText).to.not.match(/^\s*$/);
    });
  });

  it('should verify alt text is accessible to screen readers via accessibility tree', () => {
    cy.get('img').each(($img) => {
      cy.wrap($img)
        .should('have.attr', 'alt')
        .then((altText) => {
          expect(altText).to.be.a('string');
          expect(altText.trim().length).to.be.greaterThan(0);
        });
    });
  });

  it('should handle edge case of images with very long alt text', () => {
    cy.get('img').each(($img) => {
      const altText = $img.attr('alt');

      if (altText) {
        expect(altText.length).to.be.lessThan(500);
        expect(altText).to.not.contain('\n\n');
      }
    });
  });

  it('should verify linked images have descriptive alt text', () => {
    cy.get('a img').each(($img) => {
      const altText = $img.attr('alt');
      const parentLink = $img.closest('a');

      expect(altText).to.exist;
      expect(altText).to.not.be.empty;

      if (!altText || altText.trim() === '') {
        cy.wrap(parentLink)
          .should('have.attr', 'aria-label')
          .and('not.be.empty');
      }
    });
  });

  it('should verify background images have alternative text content', () => {
    cy.get('[style*="background-image"]').each(($el) => {
      const hasAriaLabel = $el.attr('aria-label');
      const hasTitle = $el.attr('title');
      const hasTextContent = $el.text().trim().length > 0;

      const hasAccessibleName = hasAriaLabel || hasTitle || hasTextContent;
      expect(hasAccessibleName).to.be.true;
    });
  });
});
